#!/bin/sh
# Generated by `codeyam-editor editor devcontainer-setup`. Keeps this
# codespace awake while the CodeYam Editor is busy (an agent is working or
# the editor tab is open): GitHub only counts terminal output as activity,
# so this prints a line every few minutes while busy and nothing otherwise,
# letting an unused codespace still stop at its idle timeout.

port=14199
interval="${CODEYAM_KEEPALIVE_INTERVAL:-240}"

while :; do
  if curl -s --max-time 5 "http://127.0.0.1:$port/api/activity" | grep -q '"busy":true'; then
    echo "[keep-alive $(date +%H:%M)] editor busy — keeping this codespace awake"
  fi
  sleep "$interval"
done
